// Included inside udm, before Options.
inline void progressPreferences(CWnd* owner,Json& prefs){Form d("Download dialog settings",472,279,owner);d.init=[&]{d.label("Start download progress windows:",13,15,443);auto state=d.combo({"Normal size","Small size","Minimized"},str(prefs,"ProgressStartMode","Normal size"),13,41,443);auto speed=d.check("Show Speed Limiter tab",yes(prefs,"ProgressSpeedTab",true),13,84,443);auto info=d.check("Show Download information tab",yes(prefs,"ProgressInformationTab",true),13,117,443);auto queue=d.check("Start queue progress windows minimized",yes(prefs,"QueueProgressMinimized",true),13,151,443);d.label("Changes apply to newly opened progress windows. Hidden windows can be restored by double-clicking the download.",13,188,443,39);d.accept=[&,state,speed,info,queue]{prefs["ProgressStartMode"]=text(state);prefs["ProgressSpeedTab"]=d.checked(speed);prefs["ProgressInformationTab"]=d.checked(info);prefs["QueueProgressMinimized"]=d.checked(queue);d.close();};d.button("OK",267,239,89,d.accept);d.button("Cancel",367,239,89,[&]{d.close(IDCANCEL);});};d.DoModal();}
inline void playDownloadSound(const Json& prefs,const char* enabled,const char* key){if(!yes(prefs,enabled,std::string(enabled)=="Sound"))return;auto path=str(prefs,key);if(path.empty())MessageBeep(MB_OK);else PlaySoundW(wide(path).c_str(),nullptr,SND_FILENAME|SND_ASYNC|SND_NODEFAULT);}
